
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_rregtm_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_rregtm", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.650614430549054e-02, -2.645881780470617e-02, -2.638867555152631e-02, -2.628337433696043e-02, -2.612244169935218e-02, -2.587070056658937e-02, -2.546843221729262e-02, -2.486358456245995e-02, -2.498962667428257e-02, -3.102504984001015e-02, -2.879334574837210e-02, -4.204391739633791e-02, -4.696313393546251e-02, -3.392068987392403e-02, -2.446736700499866e-02, -1.517870450019252e-02, -6.805254840632726e-03, -1.940376865558317e-03, -2.847616347885133e-04, -1.501395383699947e-05]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


